const SEGMENTS = 12;
const NAMES = ['빨강', '주황', '노랑', '연두', '초록', '청록', '하늘', '파랑', '남색', '보라', '자주', '분홍'];

export default function ColorWheelPage({ accent }: { accent: string }) {
  const [selected, setSelected] = useState(0);
  const size = 320;
  const center = size / 2;
  const radius = center - 6;
  const inner = 84;

  const arc = (i: number, r1: number, r2: number) => {
    const start = (i / SEGMENTS) * 2 * Math.PI - Math.PI / 2;
    const end = ((i + 1) / SEGMENTS) * 2 * Math.PI - Math.PI / 2;
    const p = (ang: number, r: number) => [center + r * Math.cos(ang), center + r * Math.sin(ang)];
    const [x1, y1] = p(start, r2);
    const [x2, y2] = p(end, r2);
    const [ix1, iy1] = p(start, r1);
    const [ix2, iy2] = p(end, r1);
    return `M ${x1} ${y1} A ${r2} ${r2} 0 0 1 ${x2} ${y2} L ${ix2} ${iy2} A ${r1} ${r1} 0 0 0 ${ix1} ${iy1} Z`;
  };

  const hueOf = (i: number) => (i / SEGMENTS) * 360;
  const selHue = hueOf(selected);
  const selHex = hslToHex(selHue, 85, 55);
